// Normalizes both Meta WhatsApp Cloud API payload and direct JSON testing
const body = $input.item.json.body || $input.item.json;
let phone = "";
let message = "";
let attachmentType = null;
let attachmentData = null;

// 1. Check if Meta WhatsApp Cloud API format
if (body.entry && body.entry[0]?.changes && body.entry[0].changes[0]?.value?.messages) {
  const waMsg = body.entry[0].changes[0].value.messages[0];
  phone = waMsg.from;
  if (waMsg.type === 'text') {
    message = waMsg.text.body;
  } else if (waMsg.type === 'image') {
    message = waMsg.image.caption || 'Image report received';
    attachmentType = 'image';
    attachmentData = waMsg.image.id;
  } else if (waMsg.type === 'document') {
    message = waMsg.document.caption || 'Document report received';
    attachmentType = 'document';
    attachmentData = waMsg.document.id;
  }
} else {
  // 2. Direct JSON payload (e.g. from simulator or test script)
  phone = body.phone || body.from || "+919876543210";
  message = body.message || body.text || "";
  attachmentType = body.attachment_type || null;
  attachmentData = body.attachment_data || null;
}

// Format phone with + if missing
if (phone && !phone.startsWith('+')) {
  phone = '+' + phone;
}

return [{
  json: {
    phone,
    message,
    channel: 'whatsapp',
    attachment_type: attachmentType,
    attachment_data: attachmentData,
    raw_incoming: body
  }
}];

// Trigger alert to clinic emergency duty group / doctor
const data = $input.item.json;
const alertMsg = `🚨 *URGENT MEDICAL ALERT*\n\n` +
  `*Patient:* ${data.patient?.name} (${data.patient?.district})\n` +
  `*Phone:* ${data.patient?.phone || 'N/A'}\n` +
  `*Reason:* ${data.intent_analysis?.patient_reason || 'Urgent symptom reported'}\n` +
  `*Confidence:* ${(data.intent_analysis?.confidence * 100).toFixed(0)}%\n` +
  `*Follow-up Status:* ${data.new_status}\n\n` +
  `*Immediate Action Required by On-Duty Doctor/Nurse!*`;

return [{
  json: {
    alert_type: 'DOCTOR_ALERT',
    alert_message: alertMsg,
    patient: data.patient,
    reply_message: data.reply_message
  }
}];

